INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (389, 1, '컴퓨트 로그 위치', 'Nova 의 **컴퓨트 서비스 로그** 는 기본으로 어디에 쌓일까요?', '서비스마다 파일이 따로 있어요.', NULL, NULL, '[]', 'choice', '["`/etc/nova` 아래에 하나의 큰 로그 파일이 있다", "`/tmp/nova.log` 하나에 모든 서비스가 섞여 쌓인다", "`/var/log/nova` 에 서비스마다 로그 파일이 있다", "로그는 파일로 남지 않고 인스턴스 안에만 있다"]', 2, 'Nova 문서는 컴퓨트 서비스마다 `/var/log/nova` 에 로그 파일을 하나씩 두고 예를 들어 `nova-compute.log` 가 nova-compute 서비스의 로그라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 2, '흔한 문제들', '컴퓨트에서 **흔히 만나는 문제** 로 문서가 꼽는 것은 무엇일까요?', '환경과 이미지 쪽 문제예요.', NULL, NULL, '[]', 'choice', '["디스크가 너무 많이 남아서 생기는 성능 저하 문제", "네트워크 설정 오류, 인증 정보 미적용, 32비트 이미지", "인스턴스 이름에 한글을 쓴 경우에 생기는 오류", "플레이버의 이름이 너무 길어서 생기는 오류"]', 1, '문서는 컴퓨트의 흔한 문제가 대개 잘못된 네트워킹이나 환경에 제대로 불러오지 않은 인증 정보이며, 평면(flat) 네트워크에서는 컴퓨트 노드에서 인스턴스로 ping/ssh 가 안 되는 경우가 많고, 64비트 컴퓨트 노드에서 32비트 이미지를 실행하려는 것도 흔한 문제라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 3, 'BUILD 에서 ERROR', 'KVM 호스트에서 VM 을 만들면 BUILD 다음 **ERROR** 가 되고 "적합한 에뮬레이터를 찾을 수 없다"고 합니다. 먼저 확인할 것은 무엇일까요?', '하드웨어 가상화 지원 표시예요.', NULL, NULL, '[]', 'choice', '["호스트 `/proc/cpuinfo` 의 `vmx` 또는 `svm` 플래그", "호스트 `/etc/hosts` 에 인스턴스 이름이 있는지 여부", "인스턴스 안의 `/var/log/messages` 파일이 큰지 여부", "플레이버의 이름이 영문으로만 되어 있는지 여부"]', 0, '문서는 이 증상의 해결로 KVM 호스트에서 `cat /proc/cpuinfo` 를 해 `vmx` 또는 `svm` 플래그가 켜져 있는지 확인하고, BIOS 에서 하드웨어 가상화 지원을 켜라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 4, '볼륨 재연결 실패', '볼륨을 떼었다가 **같은 볼륨을 다시 붙이면 실패** 합니다. 문서가 알려 주는 해결은 무엇일까요?', '예전 장치 이름이 남아 있을 수 있어요.', NULL, NULL, '[]', 'choice', '["볼륨을 삭제하고 새로 만든다", "인스턴스를 삭제하고 다시 만든다", "장치 이름은 바꿀 수 없으므로 포기한다", "붙일 때 **다른 장치 이름** 을 지정한다"]', 3, '문서는 detach 뒤 VM 이 정리를 덜 해서 같은 장치 이름으로 attach 가 실패할 수 있으니 attach 명령에서 장치 이름을 바꾸라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 5, '콘솔 로그가 비어 있을 때', '인스턴스의 **콘솔 로그가 비어 있어** 아무것도 볼 수 없습니다. 문서의 해결은 무엇일까요?', '부트로더 설정을 고쳐요.', NULL, NULL, '[]', 'choice', '["호스트의 nova 서비스를 모두 지우고 다시 설치한다", "인스턴스의 플레이버를 더 큰 것으로 바꿔 준다", "부트로더 인자에 `console=ttyS0` 류를 추가한다", "보안 그룹에서 모든 포트를 열어서 접속해 본다"]', 2, '문서는 콘솔 출력이 Compute 서비스로 가도록 부트로더 커널 인자에 `console=tty0 console=ttyS0,115200n8` 을 덧붙이고 재부팅하라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 6, '삭제 중에 멈춘 인스턴스', '인스턴스가 `deleting` 같은 **중간 상태에서 멈춰** 있습니다. 문서가 알려 주는 방법은 무엇일까요?', '상태를 먼저 바꿔요.', NULL, NULL, '[]', 'choice', '["호스트를 재부팅하면 항상 자동으로 정리된다", "`reset-state` 로 오류 상태로 바꾼 뒤 삭제한다", "볼륨을 먼저 지우면 인스턴스는 자동 삭제된다", "그 상태에서는 어떤 방법도 없어 영구히 남는다"]', 1, '문서는 인스턴스가 deleting 같은 중간 상태에 머물 때 reset-state 로 오류 상태로 되돌린 뒤 `openstack server delete` 로 삭제하는 방법을 설명합니다.', NULL, NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 7, 'rescue 의 기본 동작', '`openstack server rescue SERVER` 를 하면 **기본 모드** 에서 인스턴스는 어떻게 부팅될까요?', '이미지가 망가져 접근이 안 될 때 쓰는 기능이에요.', NULL, NULL, '[]', 'choice', '["rescue 이미지(없으면 원본 복사본)로 부팅한다", "원래 루트 디스크로 그대로 다시 부팅해 준다", "인스턴스를 삭제하고 같은 이름으로 새로 만든다", "인스턴스에 붙은 볼륨을 모두 새로 포맷해 버린다"]', 0, '문서는 기본적으로 rescue 이미지(없으면 원본 이미지의 새 복사본)로 부팅하고 루트 디스크와 필요 시 다시 만든 config drive 를 데이터 복구용으로 붙인다고 설명합니다. rescue 전에 소프트 종료를 먼저 합니다.', NULL, NULL, NULL, '[{"title": "Nova 인스턴스 구조(rescue)", "url": "https://docs.openstack.org/nova/latest/user/rescue.html"}]'),
  (389, 8, '볼륨 기반 인스턴스의 rescue', '**볼륨 기반(volume-backed)** 인스턴스를 rescue 하려면 어떤 모드가 필요할까요?', 'Ussuri 에 추가된 모드예요.', NULL, NULL, '[]', 'choice', '["기본 모드로 가능하며 추가 설정이 필요 없다", "볼륨 기반 인스턴스는 어떤 모드로도 rescue 할 수 없다", "인스턴스를 먼저 이미지 기반으로 바꾼 뒤에만 가능하다", "안정 장치(stable device) rescue 모드"]', 3, '문서는 기본 모드가 볼륨 기반 인스턴스의 rescue 를 지원하지 않고, 21.0.0(Ussuri)에 추가된 안정 장치 rescue 모드가 볼륨 기반 인스턴스를 지원한다고 설명합니다. 이 모드는 rescue 이미지의 `hw_rescue_device`·`hw_rescue_bus` 속성으로 제어됩니다.', NULL, NULL, NULL, '[{"title": "Nova 인스턴스 구조(rescue)", "url": "https://docs.openstack.org/nova/latest/user/rescue.html"}]'),
  (389, 9, '병렬 생성과 어피니티', '**anti-affinity 서버 그룹** 으로 서버 생성 요청을 **동시에 여러 개** 보내면 어떤 일이 생길 수 있을까요?', '정책 확인이 요청마다 따로 일어나요.', NULL, NULL, '[]', 'choice', '["항상 정책이 지켜지고 위반하는 요청은 모두 실패한다", "요청이 자동으로 한 줄로 직렬화되어 정책이 지켜진다", "같은 호스트에 놓이고도 ACTIVE 가 되어 정책이 깨질 수 있다", "서버 그룹이 자동으로 삭제되어 정책이 사라진다"]', 2, '문서는 병렬 생성 요청이 어피니티·안티어피니티 정책을 위반해 같은 호스트에 놓이고도 서버가 ACTIVE 가 될 수 있다고 설명합니다. 해결로 여러 서버를 단일 다중 생성 요청으로 만들 것을 제안합니다.', NULL, NULL, NULL, '[{"title": "Nova 병렬 요청의 어피니티 위반", "url": "https://docs.openstack.org/nova/latest/admin/troubleshooting/affinity-policy-violated.html"}]'),
  (389, 10, '상태 초기화', '중간 상태에 멈춘 인스턴스를 **오류 상태로 되돌리는** 명령입니다. 빈칸을 채우세요.', '"상태를 초기화"예요.', NULL, NULL, '[]', 'fill', '["reset-state", "clear-status", "force-delete", "revert"]', NULL, '문서는 `nova reset-state` 로 인스턴스 상태를 오류로 수동 초기화한 뒤 삭제하라고 설명합니다. `force-delete` 는 실제로 있는 다른 명령이지만 이 용도의 설명과 다릅니다.', '[0]', 'nova {0} SERVER', NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]'),
  (389, 11, '다중 생성으로 막기', '어피니티 정책이 지켜지도록 서버 여러 대를 **한 번의 요청** 으로 만드는 CLI 옵션입니다. 빈칸을 채우세요.', '최소 개수(min)를 줘요.', NULL, NULL, '[]', 'fill', '["min", "batch", "group", "repeat"]', NULL, '문서는 병렬 생성 요청 때문에 어피니티/안티어피니티 정책이 깨질 수 있으니 다중 생성 API 의 `min_count` 또는 CLI 의 `--min` 옵션으로 여러 서버를 한 요청으로 만들라고 설명합니다.', '[0]', 'openstack server create --{0} 3 ...', NULL, '[{"title": "Nova 병렬 요청의 어피니티 위반", "url": "https://docs.openstack.org/nova/latest/admin/troubleshooting/affinity-policy-violated.html"}]'),
  (389, 12, '인스턴스가 ERROR 일 때 살피기', '인스턴스가 ERROR 가 되었을 때 원인을 좁히는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '상태 → 이유 → 로그 → 조치 순서예요.', NULL, NULL, '[]', 'order', '["`openstack server show` 로 상태와 fault(오류 메시지)를 확인한다", "`/var/log/nova` 의 해당 서비스 로그에서 같은 시각의 오류를 찾는다", "원인(가상화 플래그, 네트워크, 인증 정보 등)을 확인하고 고친다", "고친 뒤 인스턴스를 다시 만들거나 상태를 되돌려 확인한다"]', NULL, '상태와 fault 로 대략을 보고 서비스 로그에서 구체적 원인을 찾아 고친 뒤 다시 시도하는 일반적인 절차입니다. 흔한 원인은 문서가 정리한 대로 가상화 플래그, 네트워크 설정, 인증 정보 등입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "Nova 문제 해결", "url": "https://docs.openstack.org/nova/latest/admin/support-compute.html"}]');
